package ktanesolver.module.modded.regular.modulo;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service@ModuleInfo(type=ModuleType.MODULO,id="modulo",name="Modulo",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Take the remainder of the large number divided by the corner number.",tags={"math","remainder","keypad"})public class ModuloSolver extends AbstractModuleSolver<ModuloInput,ModuloOutput>{@Override protected SolveResult<ModuloOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,ModuloInput input){if(input==null||input.number()==null||input.modulo()==null)return failure("Enter both displayed numbers");if(input.number()<50||input.number()>999)return failure("The central number must be from 50 through 999");if(input.modulo()<3||input.modulo()>15)return failure("The corner number must be from 3 through 15");return success(new ModuloOutput(input.number()%input.modulo()));}}
